begin;
do $test$
declare extra_id uuid; extra_ids uuid[]:='{}'; outsider uuid:=gen_random_uuid(); invalid_ids uuid[]; sh uuid; foreign_shop uuid; svc uuid; alt uuid; addon uuid; foreign_svc uuid; cut uuid; barber uuid; other_barber uuid; owner_id uuid:=gen_random_uuid(); booking record; replay record; manual record; offered record; claimed record; d date:=(now() at time zone 'Africa/Maputo')::date+3; start_at timestamptz; slug text:='composition-test-'||left(gen_random_uuid()::text,8); k uuid:=gen_random_uuid(); payload jsonb; hash text:=repeat('a',64);
begin
 insert into public.barbershops(slug,name,status,timezone,min_lead_time_min,max_advance_days,slot_interval_min) values(slug,'Composition fixture','active','Africa/Maputo',30,30,15) returning id into sh;
 insert into public.barbershops(slug,name,status,timezone) values(slug||'-foreign','Foreign fixture','active','Africa/Maputo') returning id into foreign_shop;
 insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(sh,'Corte Clássico',25000,30,true) returning id into svc;
 insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(sh,'Corte + Barba',50000,45,true) returning id into alt;
 insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(sh,'Lavagem e finalização',8000,15,true) returning id into addon;
 insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(foreign_shop,'Foreign fixture',100,15,true) returning id into foreign_svc;
 if not exists(select 1 from public.services where id=svc and category='Cabelo' and subcategory='Cortes') or not exists(select 1 from public.service_addons where service_id=svc and addon_service_id=addon) then raise exception 'FUTURE_CATALOG_NOT_PROVISIONED'; end if;
 insert into public.barbers(barbershop_id,display_name,is_active) values(sh,'Qualified fixture',true) returning id into barber;
 insert into public.barbers(barbershop_id,display_name,is_active) values(sh,'Unqualified fixture',true) returning id into other_barber;
 insert into public.barber_services(barber_id,service_id) values(barber,svc),(barber,alt),(barber,addon),(other_barber,svc),(other_barber,alt);
 insert into public.working_hours(barbershop_id,barber_id,weekday,opens_at,closes_at,is_closed) select sh,b.id,n,time '09:00',time '12:00',false from (values(barber),(other_barber)) b(id) cross join generate_series(0,6)n;
 insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(owner_id,'authenticated','authenticated',owner_id::text||'@example.invalid','',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{}'::jsonb,now(),now());
 insert into public.barbershop_members(barbershop_id,user_id,role) values(sh,owner_id,'owner');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id::text,'role','authenticated')::text,true);
 set local role authenticated;
 select public.save_haircut_configuration(sh,null,jsonb_build_object('name','Multi offer','service_id',svc,'price_cents',30000,'duration_min',45,'skill_restricted',true),jsonb_build_array(jsonb_build_object('service_id',alt,'price_cents',65000,'duration_min',60)),array[barber]) into cut;
 perform public.save_service_configuration(sh,svc,jsonb_build_object('name','Corte Clássico','price_cents',25000,'duration_min',30,'category','Cabelo','subcategory','Cortes','requires_deposit',false),array[addon]);
 begin perform public.save_service_configuration(sh,svc,jsonb_build_object('name','Invalid','price_cents',1,'duration_min',30,'category','Cabelo','subcategory','Cortes'),array[foreign_svc]); raise exception 'CROSS_TENANT_ADDON_ACCEPTED'; exception when others then if sqlerrm<>'TENANT_RELATION_MISMATCH' then raise; end if; end;
 begin perform public.save_haircut_configuration(sh,cut,jsonb_build_object('name','Invalid','service_id',foreign_svc),'[]'::jsonb,'{}'::uuid[]); raise exception 'CROSS_TENANT_STYLE_ACCEPTED'; exception when others then if sqlerrm<>'TENANT_RELATION_MISMATCH' then raise; end if; end;
 reset role;
 -- Stress boundaries: no partial writes, cross-tenant reads, qualification and malformed input.
 insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(outsider,'authenticated','authenticated',outsider::text||'@example.invalid','',now(),'{"provider":"email","providers":["email"]}','{}',now(),now());
 insert into public.barbershop_members(barbershop_id,user_id,role) values(foreign_shop,outsider,'owner');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider::text,'role','authenticated')::text,true);
 set local role authenticated;
 if exists(select 1 from public.service_addons where barbershop_id=sh) or exists(select 1 from public.haircut_service_offers where barbershop_id=sh) or exists(select 1 from public.haircut_barber_skills where barbershop_id=sh) then raise exception 'RELATION_RLS_LEAK'; end if;
 begin perform public.save_service_configuration(sh,svc,jsonb_build_object('name','Unauthorized','price_cents',1,'duration_min',30,'category','Cabelo','subcategory','Cortes'),array[addon]); raise exception 'UNAUTHORIZED_WRITE'; exception when others then if sqlerrm<>'FORBIDDEN' then raise; end if; end;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id::text,'role','authenticated')::text,true);
 foreach invalid_ids slice 1 in array array[array[svc],array[foreign_svc],array[gen_random_uuid()],array[null::uuid]] loop
   begin perform * from private.resolve_booking_composition(sh,svc,cut,invalid_ids); raise exception 'INVALID_ADDON_ACCEPTED'; exception when others then if sqlerrm<>'INVALID_BOOKING_OFFER' then raise; end if; end;
 end loop;
 for n in 1..6 loop
   insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(sh,'Stress add-on '||n,1000,10,true) returning id into extra_id;
   insert into public.service_addons(barbershop_id,service_id,addon_service_id) values(sh,svc,extra_id);
   insert into public.barber_services(barber_id,service_id) values(barber,extra_id);
   extra_ids:=array_append(extra_ids,extra_id);
 end loop;
 if not exists(select 1 from private.resolve_booking_composition(sh,svc,cut,extra_ids[1:5]) where price_cents=35000 and duration_min=95 and jsonb_array_length(components)=6) then raise exception 'FIVE_ADDONS_FAILED'; end if;
 begin perform * from private.resolve_booking_composition(sh,svc,cut,extra_ids); raise exception 'SIX_ADDONS_ACCEPTED'; exception when others then if sqlerrm<>'INVALID_BOOKING_OFFER' then raise; end if; end;
 update public.services set duration_min=480 where id=extra_ids[1];
 begin perform * from private.resolve_booking_composition(sh,svc,cut,extra_ids[1:1]); raise exception 'OVERLONG_COMPOSITION_ACCEPTED'; exception when others then if sqlerrm<>'INVALID_BOOKING_OFFER' then raise; end if; end;
 update public.services set duration_min=10,is_active=false where id=extra_ids[1];
 begin perform * from private.resolve_booking_composition(sh,svc,cut,extra_ids[1:1]); raise exception 'INACTIVE_ADDON_ACCEPTED'; exception when others then if sqlerrm<>'INVALID_BOOKING_OFFER' then raise; end if; end;
 update public.haircuts set skill_restricted=true where id=cut;
 delete from public.haircut_barber_skills where haircut_id=cut;
 if exists(select 1 from public.get_composed_available_slots(slug,svc,null,d,cut,array[addon])) then raise exception 'EMPTY_SKILL_SET_AVAILABLE'; end if;
 insert into public.haircut_barber_skills(barbershop_id,haircut_id,barber_id) values(sh,cut,barber);
 delete from public.service_addons where service_id=svc and addon_service_id=any(extra_ids);
 delete from public.services where id=any(extra_ids);
 if not exists(select 1 from private.resolve_booking_offer(sh,alt,cut) where price_cents=65000 and duration_min=60) then raise exception 'SECONDARY_PRICE_NOT_RESOLVED'; end if;
 if not exists(select 1 from private.resolve_booking_composition(sh,svc,cut,array[addon]) where price_cents=38000 and duration_min=60 and jsonb_array_length(components)=2) then raise exception 'COMPOSITION_NOT_RESOLVED'; end if;
 begin perform * from private.resolve_booking_composition(sh,svc,cut,array[addon,addon]); raise exception 'DUPLICATE_ADDON_ACCEPTED'; exception when others then if sqlerrm<>'INVALID_BOOKING_OFFER' then raise; end if; end;
 if exists(select 1 from public.get_offer_available_slots(slug,alt,other_barber,d,cut)) then raise exception 'UNTRAINED_BARBER_AVAILABLE'; end if;
 if exists(select 1 from public.get_composed_available_slots(slug,svc,other_barber,d,null,array[addon])) then raise exception 'ADDON_UNQUALIFIED_BARBER_AVAILABLE'; end if;
 if not exists(select 1 from public.get_composed_available_days(slug,svc,null,d,d,cut,array[addon]) where day=d and slots_count>0) then raise exception 'COMPOSED_DAY_NOT_AVAILABLE'; end if;
 select min(slot_start) into start_at from public.get_composed_available_slots(slug,svc,null,d,cut,array[addon]);
 begin perform * from public.book_composed_appointment_with_shop_order_idempotent(k,slug,svc,cut,null,start_at,'Quote fixture','840000015',null,'[]'::jsonb,hash,array[addon],1,60); raise exception 'STALE_QUOTE_ACCEPTED'; exception when others then if sqlerrm<>'BOOKING_QUOTE_CHANGED' then raise; end if; end;
 select * into booking from public.book_composed_appointment_with_shop_order_idempotent(k,slug,svc,cut,null,start_at,'Composition fixture','840000015',null,'[]'::jsonb,hash,array[addon],38000,60);
 select * into replay from public.book_composed_appointment_with_shop_order_idempotent(k,slug,svc,cut,null,start_at,'Composition fixture','840000015',null,'[]'::jsonb,hash,array[addon],38000,60);
 if booking.appointment_id<>replay.appointment_id then raise exception 'COMPOSITION_IDEMPOTENCY_FAILED'; end if;
 if not exists(select 1 from public.appointments a where a.id=booking.appointment_id and a.barber_id=barber and a.price_cents=38000 and a.duration_min=60 and jsonb_array_length(a.service_components)=2) then raise exception 'COMPOSITION_SNAPSHOT_FAILED'; end if;
 if exists(select 1 from public.get_composed_available_slots(slug,svc,barber,d,cut,array[addon]) where slot_start=start_at+interval '45 minutes') then raise exception 'COMPOSITION_OVERLAP'; end if;
 if not exists(select 1 from public.get_appointment_by_token(booking.manage_token) where service_name='Corte Clássico + Lavagem e finalização' and service_price_cents=38000 and service_duration_min=60) then raise exception 'TOKEN_COMPOSITION_LABEL_FAILED'; end if;
 set local role authenticated;
 if not exists(select 1 from public.get_agenda_appointments(sh,start_at-interval '1 hour',start_at+interval '2 hours') where service_name='Corte Clássico + Lavagem e finalização') then raise exception 'AGENDA_COMPOSITION_LABEL_FAILED'; end if;
 begin perform * from public.reschedule_appointment_by_operator(sh,booking.appointment_id,start_at+interval '1 day',other_barber); raise exception 'UNQUALIFIED_REASSIGNMENT_ACCEPTED'; exception when others then if sqlerrm<>'BARBER_NOT_FOUND' then raise; end if; end;
 select * into manual from public.book_composed_appointment_manual(sh,svc,cut,barber,start_at+interval '1 day','Manual composition','840000016',null,null,array[addon],38000,60);
 reset role;
 if not exists(select 1 from public.appointments a where a.id=manual.appointment_id and a.source='manual' and a.price_cents=38000 and a.duration_min=60) then raise exception 'MANUAL_COMPOSITION_FAILED'; end if;
 perform * from public.join_composed_waitlist(slug,svc,'Waitlist composition','840000017',cut,barber,null,d+2,d+2,'any',array[addon]);
 select * into offered from private.offer_next_waitlist_core(sh,start_at+interval '2 days',barber);
 if offered.offer_token is null then raise exception 'COMPOSED_WAITLIST_OFFER_MISSING'; end if;
 if not exists(select 1 from public.get_waitlist_offer(offered.offer_token) where service_price_cents=38000 and service_duration_min=60 and service_name='Corte Clássico + Lavagem e finalização') then raise exception 'COMPOSED_WAITLIST_QUOTE_FAILED'; end if;
 select * into claimed from public.claim_waitlist_offer(offered.offer_token);
 if not exists(select 1 from public.appointments a where a.id=claimed.appointment_id and a.source='waitlist' and a.price_cents=38000 and a.duration_min=60) then raise exception 'COMPOSED_WAITLIST_CLAIM_FAILED'; end if;
 update public.services set name='Changed add-on',price_cents=10000,duration_min=20 where id=addon;
 if not exists(select 1 from public.get_appointment_by_token(booking.manage_token) where service_name='Corte Clássico + Lavagem e finalização' and service_price_cents=38000 and service_duration_min=60) then raise exception 'SNAPSHOT_RENAMED'; end if;
 perform * from public.reschedule_appointment_by_token(booking.manage_token,start_at+interval '3 days');
 if not exists(select 1 from public.appointments a where a.id=booking.appointment_id and a.ends_at=a.starts_at+interval '60 minutes') then raise exception 'COMPOSED_RESCHEDULE_FAILED'; end if;
 begin update public.appointments set service_components='[]'::jsonb where id=booking.appointment_id; raise exception 'SNAPSHOT_MUTABLE'; exception when others then if sqlerrm<>'APPOINTMENT_COMPONENTS_IMMUTABLE' then raise; end if; end;
 perform * from public.join_composed_waitlist(slug,svc,'Stale quote fixture','840000018',cut,barber,null,d+4,d+4,'any',array[addon]);
 select * into offered from private.offer_next_waitlist_core(sh,start_at+interval '4 days',barber);
 if offered.offer_token is null then raise exception 'STALE_TEST_OFFER_MISSING'; end if;
 update public.services set price_cents=11000 where id=addon;
 if exists(select 1 from public.get_waitlist_offer(offered.offer_token) where can_claim) then raise exception 'STALE_OFFER_CLAIMABLE'; end if;
 begin perform * from public.claim_waitlist_offer(offered.offer_token); raise exception 'STALE_OFFER_ACCEPTED'; exception when others then if sqlerrm<>'WAITLIST_OFFER_NOT_ACTIVE' then raise; end if; end;
 set local role authenticated;
 perform public.seed_haircut_catalogue(sh);
 if not exists(select 1 from public.haircut_service_offers o join public.haircuts h on h.id=o.haircut_id where h.barbershop_id=sh and h.name='Buzz cut' and o.service_id=alt and o.price_cents is null) then raise exception 'SECONDARY_STARTER_NOT_PROVISIONED'; end if;
 if not exists(select 1 from public.get_appointments(sh,start_at,start_at+interval '5 days',null,'Lavagem e finalização',50,0) where appointment_id=booking.appointment_id) then raise exception 'COMPOSITION_SEARCH_FAILED'; end if;
 reset role;
 update public.appointments set status='completed' where id=booking.appointment_id;
 set local role authenticated;
 if not exists(select 1 from public.get_report_services(sh,d,d+5,null) r where r.service_id=addon and r.completed_count=1 and r.estimated_revenue_cents=8000) then raise exception 'ADDON_REPORT_FAILED'; end if;
 if not exists(select 1 from public.get_report_services(sh,d,d+5,null) r where r.service_id=svc and r.completed_count=1 and r.estimated_revenue_cents=30000) then raise exception 'BASE_REPORT_FAILED'; end if;
 reset role;
 payload:=public.get_public_barbershop(slug);
 if not exists(select 1 from jsonb_array_elements(payload->'services') s where s->>'id'=svc::text and s->'addon_ids' @> jsonb_build_array(addon)) or not exists(select 1 from jsonb_array_elements(payload->'haircuts') h where h->>'id'=cut::text and jsonb_array_length(h->'additional_offers')=1 and h->'skill_barber_ids' @> jsonb_build_array(barber)) then raise exception 'PUBLIC_CATALOG_CONTRACT_FAILED'; end if;
 if has_table_privilege('anon','public.service_addons','SELECT') or has_table_privilege('authenticated','public.service_addons','INSERT') or has_function_privilege('anon','public.save_service_configuration(uuid,uuid,jsonb,uuid[])','execute') or has_function_privilege('authenticated','public.book_composed_appointment_with_shop_order_idempotent(uuid,text,uuid,uuid,uuid,timestamptz,text,text,text,jsonb,text,uuid[],integer,integer)','execute') then raise exception 'COMPOSITION_PERMISSION_BOUNDARY_FAILED'; end if;
end;
$test$;
rollback;
